<?php
declare( strict_types = 1 );

namespace Automattic\WooCommerce\Internal\Blocks;

use Automattic\Jetpack\Constants;
use Automattic\WooCommerce\Blocks\Domain\Package;
use Automattic\WooCommerce\Internal\Traits\ScriptDebug;

/**
 * Registers scripts generated by the block-library wp-build package.
 *
 * @since 11.0.0
 */
class BlockLibraryScriptRegistry {
	use ScriptDebug;

	/**
	 * Packaged path for generated block-library scripts.
	 */
	private const SCRIPTS_BUILD_PATH = 'assets/client/blocks/scripts/';

	/**
	 * Path for generated block metadata.
	 */
	private const BLOCK_METADATA_BUILD_PATH = 'assets/client/blocks/';

	/**
	 * Package instance.
	 *
	 * @var Package
	 */
	private Package $package;

	/**
	 * Constructor.
	 *
	 * @param Package $package Package instance.
	 */
	public function __construct( Package $package ) {
		$this->package = $package;
	}

	/**
	 * Initialize hooks.
	 *
	 * @internal
	 */
	final public function init(): void {
		add_action( 'init', array( $this, 'register_scripts' ), 9 );
	}

	/**
	 * Register all generated block-library scripts.
	 */
	public function register_scripts(): void {

		foreach ( $this->get_script_registry() as $script ) {

			if ( ! $this->is_valid_script_entry( $script ) ) {

				continue;
			}

			$asset_data = $this->get_asset_data( $script['asset'] );
			$src        = $this->get_script_url( $script['path'] );
			$version    = $asset_data['version'];

			/**
			 * Filters the list of script dependencies.
			 *
			 * @since 11.0.0
			 *
			 * @param array  $dependencies The list of script dependencies.
			 * @param string $handle       The script's handle.
			 * @return array
			 */
			$dependencies = apply_filters(
				'woocommerce_blocks_register_script_dependencies',
				$asset_data['dependencies'],
				$script['handle']
			);
			$dependencies = is_array( $dependencies ) ? $dependencies : array();

			wp_register_script( $script['handle'], $src, $dependencies, $version, true );

			if ( function_exists( 'wp_set_script_translations' ) ) {
				wp_set_script_translations( $script['handle'], 'woocommerce', $this->package->get_path( 'languages' ) );
				wp_set_script_translations( $script['handle'], 'woocommerce', $this->package->get_path( 'i18n/languages' ) );
			}
		}
	}

	/**
	 * Register a block type from the block-library metadata package.
	 *
	 * @param string $block_name Block metadata directory name.
	 * @return void
	 */
	public function register_block_type_from_metadata( string $block_name ): void {
		$metadata_path = $this->get_block_metadata_path( $block_name );

		if ( ! $metadata_path ) {
			return;
		}

		register_block_type_from_metadata( $metadata_path );
	}

	/**
	 * Get the metadata path for a block-library block.
	 *
	 * @param string $block_name Block directory name.
	 * @return string|false Path to metadata directory, or false if not found.
	 */
	public function get_block_metadata_path( string $block_name ) {
		$metadata_path = $this->package->get_path(
			self::BLOCK_METADATA_BUILD_PATH . $block_name . '/block.json'
		);

		if ( file_exists( $metadata_path ) && $this->has_required_render_file( $metadata_path ) ) {
			return dirname( $metadata_path );
		}

		return false;
	}

	/**
	 * Check whether the render file referenced by block metadata exists.
	 *
	 * @param string $metadata_path Absolute path to block.json.
	 * @return bool True when there is no PHP render file or the referenced render file exists.
	 */
	private function has_required_render_file( string $metadata_path ): bool {
		$metadata = wp_json_file_decode( $metadata_path, array( 'associative' => true ) );

		if ( ! is_array( $metadata ) || empty( $metadata['render'] ) || ! is_string( $metadata['render'] ) ) {
			return true;
		}

		if ( 0 !== strpos( $metadata['render'], 'file:' ) ) {
			return true;
		}

		$render_file = dirname( $metadata_path ) . '/' . substr( $metadata['render'], 5 );

		return file_exists( $render_file );
	}

	/**
	 * Get the generated script registry.
	 *
	 * @return array<int, array<string, string>> Generated script registry entries.
	 */
	private function get_script_registry(): array {
		$registry_path = $this->package->get_path( $this->get_scripts_build_path() . 'registry.php' );

		if ( ! file_exists( $registry_path ) ) {
			return array();
		}

		$registry = require $registry_path;

		return is_array( $registry ) ? $registry : array();
	}

	/**
	 * Check whether a script registry entry has the required data.
	 *
	 * @param mixed $script Script registry entry.
	 * @return bool True when the script registry entry is valid.
	 */
	private function is_valid_script_entry( $script ): bool {
		return is_array( $script )
			&& ! empty( $script['handle'] )
			&& ! empty( $script['path'] )
			&& ! empty( $script['asset'] );
	}

	/**
	 * Get script asset data.
	 *
	 * @param string $asset_path Asset path relative to the generated scripts build path.
	 * @return array{dependencies: array<int, string>, version: string}
	 */
	private function get_asset_data( string $asset_path ): array {
		$asset_file = $this->package->get_path( $this->get_scripts_build_path() . $asset_path );
		$asset      = file_exists( $asset_file ) ? require $asset_file : array();
		$version    = ! empty( $asset['version'] ) && is_string( $asset['version'] ) ? $asset['version'] : $this->get_woocommerce_version();

		return array(
			'dependencies' => ! empty( $asset['dependencies'] ) && is_array( $asset['dependencies'] )
				? $asset['dependencies']
				: array(),
			'version'      => $version,
		);
	}

	/**
	 * Get the script URL for a generated script path.
	 *
	 * @param string $script_path Script path relative to the generated scripts build path, without extension.
	 * @return string Script URL.
	 */
	private function get_script_url( string $script_path ): string {
		$scripts_build_path = $this->get_scripts_build_path();
		$relative_path      = $scripts_build_path . $script_path . $this->get_script_suffix() . '.js';

		if (
			$this->is_script_debug_enabled()
			&& ! file_exists( $this->package->get_path( $relative_path ) )
		) {
			$relative_path = $scripts_build_path . $script_path . '.min.js';
		}

		return $this->package->get_url( $relative_path );
	}

	/**
	 * Get the generated scripts build path.
	 *
	 * @return string Generated scripts build path relative to the plugin root.
	 */
	private function get_scripts_build_path(): string {
		return self::SCRIPTS_BUILD_PATH;
	}

	/**
	 * Get the WooCommerce version.
	 *
	 * @return string WooCommerce version.
	 */
	private function get_woocommerce_version(): string {
		return (string) Constants::get_constant( 'WC_VERSION' );
	}
}
